INSERT INTO prompts (slug,title,description,prompt_text,category,tags,author,date,cover_image,images,featured,liked,popularity,save_count,like_count,share_count,how_to_use) VALUES ('agent-workflow-architect','AI Agent Workflow Design Prompt','Use this AI agent workflow prompt to turn a real task into clear steps, tool permissions, review points, and a human sign-off.','You are an AI workflow architect. Design a reliable agent workflow for this goal: [GOAL].' || char(10) || '' || char(10) || 'First, ask only the questions required to define the user, desired outcome, available tools, data sensitivity, time budget, and irreversible actions. Then produce a workflow with these sections:' || char(10) || '1. Outcome and non-goals' || char(10) || '2. Inputs and source-of-truth data' || char(10) || '3. Agent roles, with one sentence on what each role owns' || char(10) || '4. Step-by-step execution with explicit handoffs' || char(10) || '5. Tool permissions for each step: read, draft, execute, or prohibited' || char(10) || '6. Checkpoints where a human must approve, especially before publishing, sending, purchasing, deleting, or changing production data' || char(10) || '7. Failure handling and rollback' || char(10) || '8. A compact test plan with success criteria' || char(10) || '' || char(10) || 'Keep every agent scoped to one job. Prefer a small workflow that can be observed and verified over a large autonomous chain. End with a ready-to-use first task prompt for the lead agent.','text','["skill","ai agent workflow prompt","workflow automation","agent planning","ai agents"]','Free Prompt Base','2026-07-24',NULL,'[]',1,0,0,0,0,0,'Replace [GOAL] with a real outcome such as "triage inbound support", "research competitor launches", or "prepare a weekly content brief". Start with draft-only tool permissions, then widen them after the workflow passes review.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title, description=excluded.description, prompt_text=excluded.prompt_text, category=excluded.category, tags=excluded.tags, author=excluded.author, date=excluded.date, cover_image=excluded.cover_image, images=excluded.images, featured=excluded.featured, how_to_use=excluded.how_to_use;
INSERT INTO prompts (slug,title,description,prompt_text,category,tags,author,date,cover_image,images,featured,liked,popularity,save_count,like_count,share_count,how_to_use) VALUES ('mcp-tool-contract-designer','Safe MCP Tool Design Prompt','Use this MCP tool design prompt to define a small, safe agent tool with input validation, confirmation steps, and clear error handling.','You are designing a Model Context Protocol tool for this capability: [CAPABILITY]. The users are [USER TYPE], and the connected system is [SYSTEM].' || char(10) || '' || char(10) || 'Create a production-ready tool contract. Include:' || char(10) || '- A precise tool name and one-sentence purpose' || char(10) || '- Input schema: each field, type, required/optional state, validation, and a realistic example' || char(10) || '- Output schema: success result, partial result, and no-result state' || char(10) || '- Side effects and the exact confirmation required before any destructive or external action' || char(10) || '- Authentication and least-privilege access requirements' || char(10) || '- Idempotency and retry behavior' || char(10) || '- Error codes with agent-facing recovery instructions' || char(10) || '- Three example calls: routine success, ambiguous input, and safe refusal' || char(10) || '' || char(10) || 'Do not create a broad do-everything tool. Break [CAPABILITY] into small composable tools when the operation mixes searching, reading, writing, or publishing. Use plain language that a coding agent can follow without guessing.','text','["skill","mcp tool design prompt","model context protocol","ai agent tools","developer"]','Free Prompt Base','2026-07-24',NULL,'[]',0,0,0,0,0,0,'Use this before implementing an MCP server or adding a new agent capability. Good inputs are narrow: "create a draft GitHub issue" is better than "manage GitHub".') ON CONFLICT(slug) DO UPDATE SET title=excluded.title, description=excluded.description, prompt_text=excluded.prompt_text, category=excluded.category, tags=excluded.tags, author=excluded.author, date=excluded.date, cover_image=excluded.cover_image, images=excluded.images, featured=excluded.featured, how_to_use=excluded.how_to_use;
INSERT INTO prompts (slug,title,description,prompt_text,category,tags,author,date,cover_image,images,featured,liked,popularity,save_count,like_count,share_count,how_to_use) VALUES ('agent-evaluation-and-security-review','AI Agent Security Testing Prompt','Use this AI agent security testing prompt to write adversarial evals for prompt injection, tool misuse, and unsafe actions before launch.','Act as an AI agent evaluator and security reviewer. Assess this agent: [AGENT DESCRIPTION]. Its tools are: [TOOLS]. Its allowed actions are: [ALLOWED ACTIONS].' || char(10) || '' || char(10) || 'Create a risk-ranked evaluation plan. Include:' || char(10) || '1. The agent''s intended behavior and explicit boundaries' || char(10) || '2. High-risk failure modes, including prompt injection from external content, wrong-recipient actions, data disclosure, looping, destructive commands, and fabricated completion' || char(10) || '3. A table of test cases with setup, adversarial input, expected safe behavior, pass/fail signal, and severity' || char(10) || '4. Tests for permission escalation, confirmation handling, retries, and partial failures' || char(10) || '5. Observability requirements: logs, trace fields, redaction, alerts, and a human review queue' || char(10) || '6. A release gate with measurable thresholds and rollback triggers' || char(10) || '' || char(10) || 'Be concrete. Write tests that a team can run this week. Flag any operation that should remain human-approved rather than automated.','text','["skill","ai agent security prompt","agent evaluation","prompt injection testing","ai safety"]','Free Prompt Base','2026-07-24',NULL,'[]',1,0,0,0,0,0,'Paste the real tool list and permissions, not a summary. Use the resulting cases as a test matrix before enabling write access or autonomous runs.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title, description=excluded.description, prompt_text=excluded.prompt_text, category=excluded.category, tags=excluded.tags, author=excluded.author, date=excluded.date, cover_image=excluded.cover_image, images=excluded.images, featured=excluded.featured, how_to_use=excluded.how_to_use;
INSERT INTO prompts (slug,title,description,prompt_text,category,tags,author,date,cover_image,images,featured,liked,popularity,save_count,like_count,share_count,how_to_use) VALUES ('multi-agent-content-quality-pipeline','Multi-Agent Content Workflow Prompt','Use this multi-agent content workflow prompt to create drafts with source checks, editor review, and no direct publishing.','You are an editorial operations lead. Design a review-first multi-agent pipeline for this content outcome: [CONTENT GOAL]. Audience: [AUDIENCE]. Available source material: [SOURCES].' || char(10) || '' || char(10) || 'Assign focused roles for research, outline, drafting, fact-checking, voice editing, and final approval. For every role define: input, output, quality bar, forbidden behavior, and handoff.' || char(10) || '' || char(10) || 'The workflow must require:' || char(10) || '- A source ledger separating verified facts, assumptions, and original analysis' || char(10) || '- A redundancy check that removes repeated ideas and generic filler' || char(10) || '- A fact-check pass that flags claims needing a primary source' || char(10) || '- A voice pass that preserves a human point of view and avoids templated language' || char(10) || '- A final editor gate before anything is published' || char(10) || '' || char(10) || 'Return a concise runbook, a content brief template, and a final publish checklist. Do not let any agent publish directly.','text','["skill","multi-agent content workflow","ai content prompt","editorial workflow","content quality"]','Free Prompt Base','2026-07-24',NULL,'[]',0,0,0,0,0,0,'Use it for newsletters, video scripts, product pages, or blog production. Replace [SOURCES] with the actual links, notes, interviews, or data the team can verify.') ON CONFLICT(slug) DO UPDATE SET title=excluded.title, description=excluded.description, prompt_text=excluded.prompt_text, category=excluded.category, tags=excluded.tags, author=excluded.author, date=excluded.date, cover_image=excluded.cover_image, images=excluded.images, featured=excluded.featured, how_to_use=excluded.how_to_use;
